private fun modPow(baseValue: Long, exponentValue: Long, mod: Long): Long {
    var base = baseValue % mod
    var exponent = exponentValue
    var result = 1L

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % mod
        }
        base = base * base % mod
        exponent = exponent shr 1
    }
    return result
}

private fun modInverse(value: Long, mod: Long): Long {
    var a = value
    var b = mod
    var x0 = 1L
    var x1 = 0L

    while (b != 0L) {
        val q = a / b

        val nextA = a - q * b
        a = b
        b = nextA

        val nextX = x0 - q * x1
        x0 = x1
        x1 = nextX
    }

    return ((x0 % mod) + mod) % mod
}

private fun multiplicativeOrder(a: Long, p: Long): Long {
    var order = p - 1
    var remaining = p - 1
    var factor = 2L

    while (factor * factor <= remaining) {
        if (remaining % factor == 0L) {
            while (remaining % factor == 0L) {
                remaining /= factor
            }
            while (order % factor == 0L &&
                modPow(a, order / factor, p) == 1L
            ) {
                order /= factor
            }
        }
        factor++
    }

    if (remaining > 1L) {
        while (order % remaining == 0L &&
            modPow(a, order / remaining, p) == 1L
        ) {
            order /= remaining
        }
    }

    return order
}

fun main() {
    val fs = FastScanner()
    val a = fs.nextLong()
    val b = fs.nextLong()
    val p = fs.nextLong()
    val x = fs.nextLong()

    val order = multiplicativeOrder(a, p)
    val period = p * order
    val inverseA = modPow(a, p - 2, p)

    var answer = 0L
    var c = b

    if (order == 1L) {
        if (c <= x) {
            answer = 1L + (x - c) / period
        }
    } else {
        val inverseP = modInverse(p % order, order)
        var r = 0L

        while (r < order) {
            var delta = (r - c) % order
            if (delta < 0) delta += order

            val k = delta * inverseP % order
            val first = c + p * k

            if (first <= x) {
                answer += 1L + (x - first) / period
            }

            c = c * inverseA % p
            r++
        }
    }

    print(answer)
}

