private class FenwickMax(size: Int) {
    private val tree = IntArray(size + 1)

    fun update(index: Int, value: Int) {
        var i = index
        while (i < tree.size) {
            if (value > tree[i]) tree[i] = value
            i += i and -i
        }
    }

    fun query(index: Int): Int {
        var i = index
        var result = 0
        while (i > 0) {
            if (tree[i] > result) result = tree[i]
            i -= i and -i
        }
        return result
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val diff = IntArray(m + 2)
    repeat(n) {
        val left = fs.nextInt()
        val right = fs.nextInt()
        diff[left]++
        diff[right + 1]--
    }

    val count = IntArray(m + 1)
    var current = 0
    for (i in 1..m) {
        current += diff[i]
        count[i] = current
    }

    val increasing = IntArray(m + 1)
    var fenwick = FenwickMax(n + 2)

    for (i in 1..m) {
        val index = count[i] + 1
        increasing[i] = fenwick.query(index) + 1
        fenwick.update(index, increasing[i])
    }

    fenwick = FenwickMax(n + 2)
    var answer = 0

    for (i in m downTo 1) {
        val index = count[i] + 1
