        do {
            c = readByte()
        } while (c <= 32)

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()

    val head = IntArray(n) { -1 }
    val to = IntArray(maxOf(0, 2 * (n - 1)))
    val next = IntArray(maxOf(0, 2 * (n - 1)))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
        head[u] = edgeCount++
    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val parent = IntArray(n) { -2 }
    val order = IntArray(n)
    parent[0] = -1
    order[0] = 0

    var orderSize = 1
    var index = 0
    while (index < orderSize) {
        val v = order[index++]
        var e = head[v]
        while (e != -1) {
            val u = to[e]
            if (u != parent[v]) {
                parent[u] = v
                order[orderSize++] = u
            }
            e = next[e]
        }
    }

    val delta = IntArray(8)
    val aCount = IntArray(8)
    val bCount = IntArray(8)

    for (state in 0 until 8) {
        delta[state] = state / 4
        aCount[state] = (state / 2) % 2 + 1
        bCount[state] = state % 2 + 1
    }

    fun cappedProduct(x: Int, y: Int): Int =
        if (x == 1 && y == 1) 1 else 2

    fun encode(d: Int, a: Int, b: Int): Int =
        d * 4 + (a - 1) * 2 + (b - 1)

    val deletedTransition = IntArray(64)
    val retainedTransition = IntArray(64)

    for (left in 0 until 8) {
        for (right in 0 until 8) {
            val pair = left * 8 + right

            val deletedA = cappedProduct(aCount[left], bCount[right])
            val deletedB = cappedProduct(bCount[left], bCount[right])
            deletedTransition[pair] = encode(delta[left], deletedA, deletedB)

            val gainWithoutEdge = delta[left]
            val gainWithEdge = 1 - delta[right]
            val retainedDelta = maxOf(gainWithoutEdge, gainWithEdge)
            val retainedA = cappedProduct(aCount[left], bCount[right])

            val retainedB = when {
                gainWithoutEdge > gainWithEdge ->
                    cappedProduct(bCount[left], bCount[right])
                gainWithoutEdge < gainWithEdge ->
                    cappedProduct(aCount[left], aCount[right])
                else -> 2
            }

            retainedTransition[pair] =
                encode(retainedDelta, retainedA, retainedB)
        }
    }

    val dp = LongArray(n * 8)
    var current = LongArray(8)
    var temporary = LongArray(8)

    for (position in n - 1 downTo 0) {
        val v = order[position]
        current.fill(0L)
        current[0] = 1L

        var e = head[v]
        while (e != -1) {
            val u = to[e]
            if (parent[u] == v) {
                temporary.fill(0L)
                val childOffset = u * 8

                for (left in 0 until 8) {
                    val leftWays = current[left]
                    if (leftWays == 0L) continue

                    for (right in 0 until 8) {
                        val rightWays = dp[childOffset + right]
                        if (rightWays == 0L) continue

                        val ways = leftWays * rightWays % MOD
                        val pair = left * 8 + right

                        var destination = deletedTransition[pair]
                        var value = temporary[destination] + ways
                        if (value >= MOD) value -= MOD
                        temporary[destination] = value

                        destination = retainedTransition[pair]
                        value = temporary[destination] + ways
                        if (value >= MOD) value -= MOD
                        temporary[destination] = value
                    }
                }

                val swap = current
                current = temporary
                temporary = swap
            }
            e = next[e]
        }

        val offset = v * 8
        for (state in 0 until 8) {
            dp[offset + state] = current[state]
        }
    }

    var answer = 0L
    for (state in 0 until 8) {
        if (bCount[state] == 1) {
            answer += dp[state]
            if (answer >= MOD) answer -= MOD
        }
    }

    print(answer)
}

