private fun stateId(d: Int, a: Int, b: Int): Int {
    return d * 4 + (a - 1) * 2 + (b - 1)
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val edgeCount = n - 1

    val head = IntArray(n) { -1 }
    val to = IntArray(edgeCount * 2)
    val next = IntArray(edgeCount * 2)
    var edgeIndex = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeIndex] = v
        next[edgeIndex] = head[u]
        head[u] = edgeIndex++
    }

    repeat(edgeCount) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val parent = IntArray(n)
    Arrays.fill(parent, -2)
    parent[0] = -1

    val order = IntArray(n)
    order[0] = 0
    var orderSize = 1
    var pos = 0

    while (pos < orderSize) {
        val u = order[pos++]
        var e = head[u]
        while (e != -1) {
            val v = to[e]
            if (parent[v] == -2) {
                parent[v] = u
                order[orderSize++] = v
            }
            e = next[e]
        }
    }

    val dValue = IntArray(8)
    val aValue = IntArray(8)
    val bValue = IntArray(8)

    for (s in 0 until 8) {
        dValue[s] = s / 4
        val rem = s % 4
        aValue[s] = rem / 2 + 1
        bValue[s] = rem % 2 + 1
    }

    val deletedTransition = IntArray(64)
    val retainedTransition = IntArray(64)

    for (p in 0 until 8) {
        for (c in 0 until 8) {
            val key = p * 8 + c

            val newA = if (aValue[p] == 1 && bValue[c] == 1) 1 else 2
            val existingCount = if (bValue[p] == 1 && bValue[c] == 1) 1 else 2

            deletedTransition[key] = stateId(
                dValue[p],
                newA,
                existingCount
            )

            val existingGain = dValue[p]
            val childGain = 1 - dValue[c]
            val candidateCount = if (aValue[p] == 1 && aValue[c] == 1) 1 else 2

            val newD: Int
            val newB: Int

            when {
                existingGain > childGain -> {
                    newD = existingGain
                    newB = existingCount
                }
                existingGain < childGain -> {
                    newD = childGain
                    newB = candidateCount
                }
                else -> {
                    newD = existingGain
                    newB = 2
                }
            }

            retainedTransition[key] = stateId(newD, newA, newB)
        }
    }

    val dp = LongArray(n * 8)
    val temp = LongArray(8)

    for (index in n - 1 downTo 0) {
        val u = order[index]
        val baseU = u * 8
        dp[baseU] = 1L

        var e = head[u]
        while (e != -1) {
            val v = to[e]
            if (parent[v] == u) {
                Arrays.fill(temp, 0L)
                val baseV = v * 8

                for (pState in 0 until 8) {
                    val parentWays = dp[baseU + pState]
                    if (parentWays == 0L) continue

                    for (childState in 0 until 8) {
                        val childWays = dp[baseV + childState]
                        if (childWays == 0L) continue

                        val ways = parentWays * childWays % MOD
                        val key = pState * 8 + childState

                        val deletedState = deletedTransition[key]
                        var value = temp[deletedState] + ways
                        if (value >= MOD) value -= MOD
                        temp[deletedState] = value

                        val retainedState = retainedTransition[key]
                        value = temp[retainedState] + ways
                        if (value >= MOD) value -= MOD
                        temp[retainedState] = value
                    }
                }

                for (s in 0 until 8) {
                    dp[baseU + s] = temp[s]
                }
            }
            e = next[e]
        }
    }

    var answer = 0L
    for (state in 0 until 8) {
        if (bValue[state] == 1) {
            answer += dp[state]
            if (answer >= MOD) answer -= MOD
        }
    }

    print(answer)
}

