        head[v] = edgeIndex++
    }

    val parent = IntArray(n)
    Arrays.fill(parent, -1)
    parent[0] = -2

    val order = IntArray(n)
    val stack = IntArray(n)
    var stackSize = 0
    var orderSize = 0
    stack[stackSize++] = 0

    while (stackSize > 0) {
        val v = stack[--stackSize]
        order[orderSize++] = v

        var e = head[v]
        while (e != -1) {
            val u = to[e]
            if (parent[u] == -1) {
                parent[u] = v
                stack[stackSize++] = u
            }
            e = next[e]
        }
    }

    val transition = IntArray(64)
    for (a in 0 until 8) {
        val da = a shr 2
        val uniqueA = (a shr 1) and 1
        val uniqueB = a and 1

        for (b in 0 until 8) {
            val db = b shr 2
            val childUniqueA = (b shr 1) and 1
            val childUniqueB = b and 1

            val newD: Int
            val newUniqueA: Int

            if (db == 0) {
                newD = 1
                newUniqueA = if (da == 0 && uniqueB == 1 && childUniqueB == 1) 1 else 0
            } else {
                newD = da
                newUniqueA =
                    if (da == 1 && uniqueA == 1 && childUniqueA == 1) 1 else 0
            }

            val newUniqueB =
                if (uniqueB == 1 && childUniqueA == 1) 1 else 0

            transition[a * 8 + b] =
                newD * 4 + newUniqueA * 2 + newUniqueB
        }
    }

    val dp = LongArray(n * 8)
    val current = LongArray(8)
    val temporary = LongArray(8)

    for (position in n - 1 downTo 0) {
        val v = order[position]
        Arrays.fill(current, 0L)

        // No retained child edges: A = B = 0, both are unique.
        current[3] = 1L

        var e = head[v]
        while (e != -1) {
            val u = to[e]
            if (parent[u] == v) {
                Arrays.fill(temporary, 0L)
                val childOffset = u * 8

                for (a in 0 until 8) {
                    val waysA = current[a]
                    if (waysA == 0L) continue

                    for (b in 0 until 8) {
                        val waysB = dp[childOffset + b]
                        if (waysB == 0L) continue

                        val ways = waysA * waysB % MOD

                        // Delete edge (v, u). The child's component must
                        // already have a unique maximum matching.
                        if ((b and 2) != 0) {
                            var value = temporary[a] + ways
                            if (value >= MOD) value -= MOD
                            temporary[a] = value
                        }

                        // Retain edge (v, u).
                        val state = transition[a * 8 + b]
                        var value = temporary[state] + ways
                        if (value >= MOD) value -= MOD
                        temporary[state] = value
                    }
                }

                for (state in 0 until 8) {
                    current[state] = temporary[state]
                }
            }
            e = next[e]
        }

        val offset = v * 8
        for (state in 0 until 8) {
            dp[offset + state] = current[state]
        }
    }

    var answer = 0L
    for (state in 0 until 8) {
        if ((state and 2) != 0) {
            answer += dp[state]
            if (answer >= MOD) answer -= MOD
        }
    }

    println(answer)
}

