fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())

    val a = st.nextLong()
    val b = st.nextLong()
    val c = st.nextLong()

    val x = a + b - c
    val y = b + c - a
    val z = c + a - b

    if (x < 0 || y < 0 || z < 0 || x % 2L != 0L || y % 2L != 0L || z % 2L != 0L) {
        print("Impossible")
    } else {
        print("${x / 2} ${y / 2} ${z / 2}")
    }
}

