import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        while (c > 32 && c != -1) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextLong(): Long = next().toLong()
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong()
    val c1 = fs.nextLong()
    val c2 = fs.nextLong()
    val people = fs.next()

    val adults = people.count { it == '1' }.toLong()
    var answer = Long.MAX_VALUE

    for (groups in 1L..adults) {
        val remaining = n - groups
        val base = remaining / groups
        val largerGroups = remaining % groups

        val squareSum =
            (groups - largerGroups) * base * base +
            largerGroups * (base + 1) * (base + 1)

        val cost = groups * c1 + c2 * squareSum
        if (cost < answer) answer = cost
    }

    print(answer)
}

