import java.io.BufferedInputStream
import java.util.Arrays

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result * sign
    }
}

private class Solver(
    private val n: Int,
    private val k: Int,
    private val values: IntArray,
    private val head: IntArray,
    private val to: IntArray,
    private val next: IntArray,
    private val originalDegree: IntArray
) {
    private val parent = IntArray(n)
    private val order = IntArray(n)
    private val degree = IntArray(n)
    private val weight = IntArray(n)
    private val down = IntArray(n)
    private val queue = IntArray(n)
    private val removed = BooleanArray(n)

    init {
        buildRootedOrder()
    }

    private fun buildRootedOrder() {
        Arrays.fill(parent, -2)
        parent[0] = -1
        order[0] = 0

        var size = 1
        var index = 0
        while (index < size) {
            val v = order[index++]
            var edge = head[v]
            while (edge != -1) {
                val u = to[edge]
                if (u != parent[v]) {
                    parent[u] = v
                    order[size++] = u
                }
                edge = next[edge]
            }
        }
    }

    fun feasible(threshold: Int): Boolean {
        var badCount = 0
        for (v in 0 until n) {
            if (values[v] < threshold) badCount++
        }
        if (badCount == 0) return true

        System.arraycopy(originalDegree, 0, degree, 0, n)
        Arrays.fill(weight, 1)
        Arrays.fill(removed, false)

        var queueStart = 0
        var queueEnd = 0

        for (v in 0 until n) {
            if (values[v] >= threshold && degree[v] <= 1) {
                queue[queueEnd++] = v
            }
        }

        while (queueStart < queueEnd) {
            val v = queue[queueStart++]
            if (removed[v]) continue
            removed[v] = true

            var neighbor = -1
            var edge = head[v]
            while (edge != -1) {
                val u = to[edge]
                if (!removed[u]) {
                    neighbor = u
                    break
                }
                edge = next[edge]
            }

            if (neighbor == -1) {
                if (weight[v] >= k) return true
                continue
            }

            degree[neighbor]--

            if (values[neighbor] < threshold) {
                if (weight[v] >= k) return true
            } else {
                weight[neighbor] += weight[v]
                if (degree[neighbor] == 1) {
                    queue[queueEnd++] = neighbor
                }
            }
        }

        var bestPath = 0

        for (index in n - 1 downTo 0) {
            val v = order[index]

            if (removed[v] || values[v] < threshold) {
                down[v] = 0
                continue
            }

            var first = 0
            var second = 0
            var edge = head[v]

            while (edge != -1) {
                val u = to[edge]
                if (parent[u] == v && !removed[u] && values[u] >= threshold) {
                    val candidate = down[u]
                    if (candidate > first) {
                        second = first
                        first = candidate
                    } else if (candidate > second) {
                        second = candidate
                    }
                }
                edge = next[edge]
            }

            down[v] = weight[v] + first
            val path = weight[v] + first + second
            if (path > bestPath) {
                bestPath = path
                if (bestPath >= k) return true
            }
        }

        return bestPath >= k
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val values = IntArray(n)
    for (i in 0 until n) values[i] = fs.nextInt()

    val head = IntArray(n) { -1 }
    val degree = IntArray(n)
    val to = IntArray(2 * (n - 1))
    val next = IntArray(2 * (n - 1))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
        head[u] = edgeCount++
        degree[u]++
    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val solver = Solver(n, k, values, head, to, next, degree)

    var low = 1
    var high = 1_000_001

    while (low + 1 < high) {
        val mid = (low + high) ushr 1
        if (solver.feasible(mid)) {
            low = mid
        } else {
            high = mid
        }
    }

    print(low)
}

