private class Solver(
    private val n: Int,
    private val k: Int,
    private val value: IntArray,
    private val head: IntArray,
    private val to: IntArray,
    private val next: IntArray
) {
    private val parent = IntArray(n) { -2 }
    private val order = IntArray(n)

    private val degree = IntArray(n)
    private val weight = IntArray(n)
    private val state = ByteArray(n)
    private val marked = BooleanArray(n)
    private val queue = IntArray(n)
    private val best1 = IntArray(n)
    private val best2 = IntArray(n)
    private val down = IntArray(n)

    init {
        buildRootedOrder()
    }

    private fun buildRootedOrder() {
        var size = 1
        order[0] = 0
        parent[0] = -1

        var index = 0
        while (index < size) {
            val u = order[index++]
            var edge = head[u]
            while (edge != -1) {
                val v = to[edge]
                if (v != parent[u]) {
                    parent[v] = u
                    order[size++] = v
                }
                edge = next[edge]
            }
        }
    }

    fun feasible(threshold: Int): Boolean {
        for (u in 0 until n) {
            if (value[u] >= threshold) {
                state[u] = 0
                weight[u] = 1
                degree[u] = 0
                marked[u] = false
            } else {
                state[u] = 3
                weight[u] = 0
                degree[u] = 0
                marked[u] = false
            }
        }

        for (u in 0 until n) {
            if (state[u].toInt() == 3) continue

            var edge = head[u]
            while (edge != -1) {
                val v = to[edge]
                if (state[v].toInt() == 3) {
                    marked[u] = true
                } else {
                    degree[u]++
                }
                edge = next[edge]
            }
        }

        var queueHead = 0
        var queueTail = 0

        for (u in 0 until n) {
            if (state[u].toInt() == 0 && !marked[u] && degree[u] <= 1) {
                state[u] = 1
                queue[queueTail++] = u
            }
        }

        var answer = 0

        while (queueHead < queueTail) {
            val u = queue[queueHead++]
            state[u] = 2

            var remainingNeighbor = -1
            var edge = head[u]
            while (edge != -1) {
                val v = to[edge]
                val s = state[v].toInt()
                if (s == 0 || s == 1) {
                    remainingNeighbor = v
                    break
                }
                edge = next[edge]
            }

            if (remainingNeighbor == -1) {
                if (weight[u] > answer) answer = weight[u]
            } else {
                val v = remainingNeighbor
                weight[v] += weight[u]
                degree[v]--

                if (!marked[v] && degree[v] <= 1 && state[v].toInt() == 0) {
                    state[v] = 1
                    queue[queueTail++] = v
                }
            }
        }

        if (answer >= k) return true

        Arrays.fill(best1, 0)
        Arrays.fill(best2, 0)

        for (index in n - 1 downTo 0) {
            val u = order[index]
            if (state[u].toInt() != 0) continue

            down[u] = weight[u] + best1[u]
            val pathValue = weight[u] + best1[u] + best2[u]
            if (pathValue > answer) answer = pathValue
            if (answer >= k) return true

            val p = parent[u]
            if (p >= 0 && state[p].toInt() == 0) {
                val candidate = down[u]
                if (candidate > best1[p]) {
                    best2[p] = best1[p]
                    best1[p] = candidate
                } else if (candidate > best2[p]) {
                    best2[p] = candidate
                }
            }
        }

        return answer >= k
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val values = IntArray(n)
    var maxValue = 0
    for (i in 0 until n) {
        values[i] = fs.nextInt()
        if (values[i] > maxValue) maxValue = values[i]
    }

    val head = IntArray(n) { -1 }
    val to = IntArray(2 * (n - 1))
    val next = IntArray(2 * (n - 1))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
