    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val solver = Solver(n, k, values, head, to, next)

    var low = 1
    var high = maxValue

    while (low < high) {
        val mid = low + (high - low + 1) / 2
