private class Solver(
    private val n: Int,
    private val k: Int,
    private val value: IntArray,
    private val head: IntArray,
    private val to: IntArray,
    private val next: IntArray
) {
    private val good = BooleanArray(n)
    private val marked = BooleanArray(n)
    private val removed = BooleanArray(n)
    private val enqueued = BooleanArray(n)
    private val degree = IntArray(n)
    private val weight = IntArray(n)
    private val parent = IntArray(n)
    private val down = IntArray(n)
    private val queue = IntArray(n)
    private val stack = IntArray(n)
    private val order = IntArray(n)

    fun canAchieve(threshold: Int): Boolean {
        var goodCount = 0

        for (u in 0 until n) {
            val isGood = value[u] >= threshold
            good[u] = isGood
            if (isGood) goodCount++

            marked[u] = false
            removed[u] = false
            enqueued[u] = false
            degree[u] = 0
            weight[u] = if (isGood) 1 else 0
        }

        if (goodCount < k) return false
        if (goodCount == n) return true

        for (u in 0 until n) {
            if (!good[u]) continue

            var edge = head[u]
            while (edge != -1) {
                val v = to[edge]
                if (good[v]) {
                    degree[u]++
                } else {
                    marked[u] = true
                }
                edge = next[edge]
            }
        }

        var queueHead = 0
        var queueTail = 0

        for (u in 0 until n) {
            if (good[u] && !marked[u] && degree[u] <= 1) {
                enqueued[u] = true
                queue[queueTail++] = u
            }
        }

        while (queueHead < queueTail) {
            val u = queue[queueHead++]
            if (removed[u]) continue
            removed[u] = true

            var remainingNeighbor = -1
            var edge = head[u]
            while (edge != -1) {
                val v = to[edge]
                if (good[v] && !removed[v]) {
                    remainingNeighbor = v
                    break
                }
                edge = next[edge]
            }

            if (remainingNeighbor != -1) {
                val v = remainingNeighbor
                weight[v] += weight[u]
                degree[v]--

                if (!marked[v] && degree[v] <= 1 && !enqueued[v]) {
                    enqueued[v] = true
                    queue[queueTail++] = v
                }
            }
        }

        Arrays.fill(parent, -2)

        for (root in 0 until n) {
            if (!good[root] || removed[root] || parent[root] != -2) continue

            var stackSize = 0
            var orderSize = 0
            parent[root] = -1
            stack[stackSize++] = root

            while (stackSize > 0) {
                val u = stack[--stackSize]
                order[orderSize++] = u

                var edge = head[u]
                while (edge != -1) {
                    val v = to[edge]
                    if (good[v] && !removed[v] && parent[v] == -2) {
                        parent[v] = u
                        stack[stackSize++] = v
                    }
                    edge = next[edge]
                }
            }

            for (index in orderSize - 1 downTo 0) {
                val u = order[index]
                var best1 = 0
                var best2 = 0

                var edge = head[u]
                while (edge != -1) {
                    val v = to[edge]
                    if (parent[v] == u) {
                        val candidate = down[v]
                        if (candidate >= best1) {
                            best2 = best1
                            best1 = candidate
                        } else if (candidate > best2) {
                            best2 = candidate
                        }
                    }
                    edge = next[edge]
                }

                down[u] = weight[u] + best1
                if (weight[u] + best1 + best2 >= k) return true
            }
        }

        return false
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val values = IntArray(n)
    var maximumValue = 0
    for (i in 0 until n) {
        values[i] = fs.nextInt()
        if (values[i] > maximumValue) maximumValue = values[i]
    }

    val head = IntArray(n) { -1 }
    val to = IntArray(2 * (n - 1))
    val next = IntArray(2 * (n - 1))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
        head[u] = edgeCount++
    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val solver = Solver(n, k, values, head, to, next)

    var low = 1
    var high = maximumValue
    var answer = 1

    while (low <= high) {
        val mid = low + (high - low) / 2
        if (solver.canAchieve(mid)) {
            answer = mid
            low = mid + 1
        } else {
            high = mid - 1
        }
    }

    print(answer)
}

import java.io.BufferedInputStream
import java.util.Arrays

private class FastScanner {
    private val input = BufferedInputStream(System.`in`, 1 shl 16)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private class Solver(
    private val n: Int,
    private val k: Int,
    private val values: IntArray,
    private val head: IntArray,
    private val to: IntArray,
    private val next: IntArray
) {
    private val good = BooleanArray(n)
    private val active = BooleanArray(n)
    private val terminal = BooleanArray(n)
    private val degree = IntArray(n)
    private val weight = IntArray(n)
    private val parent = IntArray(n)
    private val down = IntArray(n)
    private val queue = IntArray(n)
    private val stack = IntArray(n)
    private val order = IntArray(n)

    fun feasible(threshold: Int): Boolean {
        var goodCount = 0

        for (v in 0 until n) {
            val isGood = values[v] >= threshold
            good[v] = isGood
            active[v] = isGood
            terminal[v] = false
            degree[v] = 0
            weight[v] = if (isGood) 1 else 0
            parent[v] = -2
            if (isGood) goodCount++
        }

        if (goodCount < k) return false

        for (v in 0 until n) {
            if (!good[v]) continue

            var edge = head[v]
            var deg = 0
            var isTerminal = false

            while (edge != -1) {
                val u = to[edge]
                if (good[u]) deg++ else isTerminal = true
                edge = next[edge]
            }

            degree[v] = deg
            terminal[v] = isTerminal
        }

        var queueHead = 0
        var queueTail = 0
        for (v in 0 until n) {
            if (good[v] && !terminal[v] && degree[v] <= 1) {
                queue[queueTail++] = v
            }
        }

        var best = 0

        while (queueHead < queueTail) {
            val v = queue[queueHead++]
            if (!active[v]) continue

            active[v] = false
            var remainingNeighbor = -1
            var edge = head[v]

            while (edge != -1) {
                val u = to[edge]
                if (active[u]) {
                    remainingNeighbor = u
                    break
                }
                edge = next[edge]
            }

            if (remainingNeighbor == -1) {
                if (weight[v] > best) best = weight[v]
            } else {
                val u = remainingNeighbor
                weight[u] += weight[v]
                degree[u]--
                if (!terminal[u] && degree[u] == 1) {
                    queue[queueTail++] = u
                }
            }
        }

        if (best >= k) return true

        var orderSize = 0

        for (start in 0 until n) {
            if (!active[start] || parent[start] != -2) continue

            var stackSize = 0
            stack[stackSize++] = start
            parent[start] = -1

            while (stackSize > 0) {
                val v = stack[--stackSize]
                order[orderSize++] = v

                var edge = head[v]
                while (edge != -1) {
                    val u = to[edge]
                    if (active[u] && parent[u] == -2) {
                        parent[u] = v
                        stack[stackSize++] = u
                    }
                    edge = next[edge]
                }
            }
        }

        for (i in orderSize - 1 downTo 0) {
            val v = order[i]
            var largest = 0
            var secondLargest = 0

            var edge = head[v]
            while (edge != -1) {
                val u = to[edge]
                if (active[u] && parent[u] == v) {
                    val candidate = down[u]
                    if (candidate >= largest) {
                        secondLargest = largest
                        largest = candidate
                    } else if (candidate > secondLargest) {
                        secondLargest = candidate
                    }
                }
                edge = next[edge]
            }

            down[v] = weight[v] + largest
            val pathSize = weight[v] + largest + secondLargest
            if (pathSize > best) best = pathSize
            if (best >= k) return true
        }

        return false
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val values = IntArray(n)
    var maximumValue = 0
    for (i in 0 until n) {
        values[i] = fs.nextInt()
        if (values[i] > maximumValue) maximumValue = values[i]
    }

    val head = IntArray(n)
    Arrays.fill(head, -1)

    val to = IntArray(2 * (n - 1))
    val next = IntArray(2 * (n - 1))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
        head[u] = edgeCount++
    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    val solver = Solver(n, k, values, head, to, next)

    var low = 1
    var high = maximumValue
    var answer = 1

    while (low <= high) {
        val middle = (low + high) ushr 1
        if (solver.feasible(middle)) {
            answer = middle
            low = middle + 1
        } else {
            high = middle - 1
        }
    }

    print(answer)
}

