    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= length) {
            length = input.read(buffer)
            ptr = 0
            if (length <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result * sign
    }
}

private class Solver(
    private val n: Int,
    private val k: Int,
    private val values: IntArray,
    private val head: IntArray,
    private val to: IntArray,
    private val next: IntArray
) {
    private val good = BooleanArray(n)
    private val boundary = BooleanArray(n)
    private val removed = BooleanArray(n)
    private val degree = IntArray(n)
    private val weight = IntArray(n)
    private val queue = IntArray(n * 2)
    private val parent = IntArray(n)
    private val order = IntArray(n)
    private val down = IntArray(n)

    private fun canAchieve(threshold: Int): Boolean {
        var badCount = 0

        for (v in 0 until n) {
            good[v] = values[v] >= threshold
            boundary[v] = false
            removed[v] = false
            degree[v] = 0
            weight[v] = if (good[v]) 1 else 0
            if (!good[v]) badCount++
        }

        if (badCount == 0) return true

        for (v in 0 until n) {
            if (!good[v]) continue

            var edge = head[v]
            var deg = 0
            var hasBadNeighbor = false

            while (edge != -1) {
                val u = to[edge]
                if (good[u]) {
                    deg++
                } else {
                    hasBadNeighbor = true
                }
                edge = next[edge]
            }

            degree[v] = deg
            boundary[v] = hasBadNeighbor
        }

        var qHead = 0
        var qTail = 0

        for (v in 0 until n) {
            if (good[v] && !boundary[v] && degree[v] <= 1) {
                queue[qTail++] = v
            }
        }

        while (qHead < qTail) {
            val v = queue[qHead++]
            if (removed[v] || boundary[v] || degree[v] > 1) continue

            removed[v] = true
            var remainingNeighbor = -1
            var edge = head[v]

            while (edge != -1) {
                val u = to[edge]
                if (good[u] && !removed[u]) {
                    remainingNeighbor = u
                    break
                }
                edge = next[edge]
            }

            if (remainingNeighbor != -1) {
                weight[remainingNeighbor] += weight[v]
                degree[remainingNeighbor]--

                if (!boundary[remainingNeighbor] && degree[remainingNeighbor] <= 1) {
                    queue[qTail++] = remainingNeighbor
                }
            }
        }

        Arrays.fill(parent, -2)
        var orderSize = 0

        for (root in 0 until n) {
            if (!good[root] || removed[root] || parent[root] != -2) continue

            var stackSize = 0
            queue[stackSize++] = root
            parent[root] = -1

            while (stackSize > 0) {
                val v = queue[--stackSize]
                order[orderSize++] = v

                var edge = head[v]
                while (edge != -1) {
                    val u = to[edge]
                    if (good[u] && !removed[u] && parent[u] == -2) {
                        parent[u] = v
                        queue[stackSize++] = u
                    }
                    edge = next[edge]
                }
            }
        }

        for (i in orderSize - 1 downTo 0) {
            val v = order[i]
            var best1 = 0
            var best2 = 0

            var edge = head[v]
            while (edge != -1) {
                val u = to[edge]
                if (good[u] && !removed[u] && parent[u] == v) {
                    val candidate = down[u]
                    if (candidate > best1) {
                        best2 = best1
                        best1 = candidate
                    } else if (candidate > best2) {
                        best2 = candidate
                    }
                }
                edge = next[edge]
            }

            down[v] = weight[v] + best1
            if (weight[v] + best1 + best2 >= k) return true
        }

        return false
    }

    fun solve(): Int {
        var low = 1
        var high = 1_000_000

        while (low < high) {
            val mid = low + (high - low + 1) / 2
            if (canAchieve(mid)) {
                low = mid
            } else {
                high = mid - 1
            }
        }

        return low
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val values = IntArray(n) { fs.nextInt() }
    val head = IntArray(n) { -1 }
    val to = IntArray(2 * (n - 1))
    val next = IntArray(2 * (n - 1))
    var edgeCount = 0

    fun addEdge(u: Int, v: Int) {
        to[edgeCount] = v
        next[edgeCount] = head[u]
        head[u] = edgeCount++
    }

    repeat(n - 1) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        addEdge(u, v)
        addEdge(v, u)
    }

    print(Solver(n, k, values, head, to, next).solve())
}

