private class MinHeap(initialCapacity: Int = 64) {
    private var nodes = IntArray(initialCapacity)
    private var distances = IntArray(initialCapacity)
    var size = 0
        private set

    var poppedNode = 0
        private set
    var poppedDistance = 0
        private set

    fun clear() {
        size = 0
    }

    fun push(node: Int, distance: Int) {
        if (size == nodes.size) {
            nodes = nodes.copyOf(nodes.size * 2)
            distances = distances.copyOf(distances.size * 2)
        }

        var i = size++
        while (i > 0) {
            val parent = (i - 1) ushr 1
            if (distances[parent] <= distance) break
            nodes[i] = nodes[parent]
            distances[i] = distances[parent]
            i = parent
        }
        nodes[i] = node
        distances[i] = distance
    }

    fun pop() {
        poppedNode = nodes[0]
        poppedDistance = distances[0]

        val newSize = --size
        if (newSize == 0) return

        val node = nodes[newSize]
        val distance = distances[newSize]
        var i = 0

        while (true) {
            val left = i * 2 + 1
            if (left >= newSize) break
            var child = left
            val right = left + 1
            if (right < newSize && distances[right] < distances[left]) {
                child = right
            }
            if (distances[child] >= distance) break

            nodes[i] = nodes[child]
            distances[i] = distances[child]
            i = child
        }

        nodes[i] = node
        distances[i] = distance
    }
}

private class MinCostMaxFlow(private val vertexCount: Int, maxDirectedEdges: Int) {
    private val head = IntArray(vertexCount) { -1 }
    private val to = IntArray(maxDirectedEdges)
    private val next = IntArray(maxDirectedEdges)
    private val capacity = IntArray(maxDirectedEdges)
    private val cost = IntArray(maxDirectedEdges)
    private var edgeCount = 0

    fun addEdge(from: Int, destination: Int, cap: Int, edgeCost: Int) {
        to[edgeCount] = destination
        capacity[edgeCount] = cap
        cost[edgeCount] = edgeCost
        next[edgeCount] = head[from]
        head[from] = edgeCount++

        to[edgeCount] = from
        capacity[edgeCount] = 0
        cost[edgeCount] = -edgeCost
        next[edgeCount] = head[destination]
        head[destination] = edgeCount++
    }

    fun minCostFlow(source: Int, sink: Int, requiredFlow: Int): Int {
        val inf = Int.MAX_VALUE / 4
        val potential = IntArray(vertexCount)
        val distance = IntArray(vertexCount)
        val previousEdge = IntArray(vertexCount)
        val heap = MinHeap()
        var flow = 0
        var totalCost = 0

        while (flow < requiredFlow) {
            java.util.Arrays.fill(distance, inf)
            java.util.Arrays.fill(previousEdge, -1)
            distance[source] = 0
            heap.clear()
            heap.push(source, 0)

            while (heap.size > 0) {
                heap.pop()
                val v = heap.poppedNode
                val currentDistance = heap.poppedDistance
                if (currentDistance != distance[v]) continue
                if (v == sink) break

                var e = head[v]
                while (e != -1) {
                    if (capacity[e] > 0) {
                        val u = to[e]
                        val reducedCost = cost[e] + potential[v] - potential[u]
                        val newDistance = currentDistance + reducedCost
                        if (newDistance < distance[u]) {
                            distance[u] = newDistance
                            previousEdge[u] = e
                            heap.push(u, newDistance)
                        }
                    }
                    e = next[e]
                }
            }

            if (previousEdge[sink] == -1) break

            for (v in 0 until vertexCount) {
                if (distance[v] < inf) potential[v] += distance[v]
            }

            var v = sink
            while (v != source) {
                val e = previousEdge[v]
                capacity[e]--
                capacity[e xor 1]++
                totalCost += cost[e]
                v = to[e xor 1]
            }
            flow++
        }

        return totalCost
    }
