private class MinCostFlow(private val vertexCount: Int, maxEdges: Int) {
    private val head = IntArray(vertexCount) { -1 }
    private val to = IntArray(maxEdges)
    private val next = IntArray(maxEdges)
    private val capacity = IntArray(maxEdges)
    private val cost = IntArray(maxEdges)
    private var edgeCount = 0

    private val potential = IntArray(vertexCount)
    private val distance = IntArray(vertexCount)
    private val level = IntArray(vertexCount)
    private val ptr = IntArray(vertexCount)
    private val queue = IntArray(vertexCount)

    private val heap = IntArray(vertexCount)
    private val heapPosition = IntArray(vertexCount)
    private var heapSize = 0

    fun addEdge(from: Int, destination: Int, cap: Int, edgeCost: Int): Int {
        val index = edgeCount

        to[edgeCount] = destination
        capacity[edgeCount] = cap
        cost[edgeCount] = edgeCost
        next[edgeCount] = head[from]
        head[from] = edgeCount++

        to[edgeCount] = from
        capacity[edgeCount] = 0
        cost[edgeCount] = -edgeCost
        next[edgeCount] = head[destination]
        head[destination] = edgeCount++

        return index
    }

    private fun heapSwap(a: Int, b: Int) {
        val x = heap[a]
        val y = heap[b]
        heap[a] = y
        heap[b] = x
        heapPosition[x] = b
        heapPosition[y] = a
    }

    private fun heapAddOrDecrease(vertex: Int) {
        var position = heapPosition[vertex]
        if (position == -1) {
            position = heapSize++
            heap[position] = vertex
            heapPosition[vertex] = position
        }

        while (position > 0) {
            val parent = (position - 1) ushr 1
            if (distance[heap[parent]] <= distance[heap[position]]) break
            heapSwap(parent, position)
            position = parent
        }
    }

    private fun heapPoll(): Int {
        val result = heap[0]
        heapPosition[result] = -1
        --heapSize

        if (heapSize > 0) {
            heap[0] = heap[heapSize]
            heapPosition[heap[0]] = 0

            var position = 0
            while (true) {
                val left = position * 2 + 1
                if (left >= heapSize) break
                val right = left + 1
                var smallest = left

                if (right < heapSize &&
                    distance[heap[right]] < distance[heap[left]]
                ) {
                    smallest = right
                }

                if (distance[heap[position]] <= distance[heap[smallest]]) break
                heapSwap(position, smallest)
                position = smallest
            }
        }

        return result
    }

    private fun dijkstra(source: Int, sink: Int): Boolean {
        val inf = 1_000_000_000
        Arrays.fill(distance, inf)
        Arrays.fill(heapPosition, -1)
        heapSize = 0

        distance[source] = 0
        heapAddOrDecrease(source)

        while (heapSize > 0) {
            val u = heapPoll()
            val currentDistance = distance[u]

            var edge = head[u]
            while (edge != -1) {
                if (capacity[edge] > 0) {
                    val v = to[edge]
                    val reducedCost = cost[edge] + potential[u] - potential[v]
                    val newDistance = currentDistance + reducedCost

                    if (newDistance < distance[v]) {
                        distance[v] = newDistance
                        heapAddOrDecrease(v)
                    }
                }
                edge = next[edge]
            }
        }

        if (distance[sink] == inf) return false

        for (v in 0 until vertexCount) {
            if (distance[v] < inf) potential[v] += distance[v]
        }
        return true
    }

    private fun isAdmissible(from: Int, edge: Int): Boolean {
        return capacity[edge] > 0 &&
            cost[edge] + potential[from] - potential[to[edge]] == 0
    }

    private fun buildLevels(source: Int, sink: Int): Boolean {
        Arrays.fill(level, -1)
        var front = 0
        var back = 0
        queue[back++] = source
        level[source] = 0

        while (front < back) {
            val u = queue[front++]
            var edge = head[u]

            while (edge != -1) {
                val v = to[edge]
                if (level[v] == -1 && isAdmissible(u, edge)) {
                    level[v] = level[u] + 1
                    queue[back++] = v
                }
                edge = next[edge]
            }
        }

        return level[sink] != -1
    }

    private fun sendBlockingFlow(source: Int, sink: Int): Int {
        System.arraycopy(head, 0, ptr, 0, vertexCount)

        val nodeStack = IntArray(vertexCount + 1)
        val edgeStack = IntArray(vertexCount)
        var depth = 0
        var flow = 0
        nodeStack[0] = source

        while (true) {
            val u = nodeStack[depth]

            if (u == sink) {
                for (i in 0 until depth) {
                    val edge = edgeStack[i]
                    capacity[edge]--
                    capacity[edge xor 1]++
                }
                flow++
                depth = 0
                nodeStack[0] = source
                continue
            }

            var edge = ptr[u]
            while (edge != -1 &&
                !(level[to[edge]] == level[u] + 1 && isAdmissible(u, edge))
            ) {
                edge = next[edge]
                ptr[u] = edge
            }

            if (edge == -1) {
                level[u] = -1
                if (depth == 0) break

                depth--
                val parent = nodeStack[depth]
                ptr[parent] = next[edgeStack[depth]]
            } else {
                edgeStack[depth] = edge
                nodeStack[depth + 1] = to[edge]
                depth++
            }
        }

        return flow
    }

    fun minCostMaxFlow(source: Int, sink: Int, requiredFlow: Int) {
        var flow = 0

        while (flow < requiredFlow && dijkstra(source, sink)) {
            while (flow < requiredFlow && buildLevels(source, sink)) {
                val pushed = sendBlockingFlow(source, sink)
                if (pushed == 0) break
                flow += pushed
            }
        }
    }

    fun isUsed(edge: Int): Boolean = capacity[edge] == 0
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()
    val total = n * m
    val grid = IntArray(total)

    for (i in 0 until total) {
        grid[i] = fs.nextInt()
    }

    val source = total
    val sink = total + 1
    val flow = MinCostFlow(total + 2, 100_000)
    val selectedEdges = ArrayList<Pair<Int, Int>>()

    for (r in 0 until n) {
        for (c in 0 until m) {
            val id = r * m + c
            if ((r + c) and 1 == 0) {
                flow.addEdge(source, id, 1, 0)

                val dr = intArrayOf(-1, 1, 0, 0)
                val dc = intArrayOf(0, 0, -1, 1)

                for (k in 0..3) {
                    val nr = r + dr[k]
                    val nc = c + dc[k]
                    if (nr !in 0 until n || nc !in 0 until m) continue

                    val nextId = nr * m + nc
                    val edgeCost = if (grid[id] == grid[nextId]) 0 else 1
                    val edgeIndex = flow.addEdge(id, nextId, 1, edgeCost)
                    selectedEdges.add(edgeIndex to edgeCost)
                }
            } else {
                flow.addEdge(id, sink, 1, 0)
            }
        }
    }

    flow.minCostMaxFlow(source, sink, total / 2)

    var answer = 0
    for ((edge, edgeCost) in selectedEdges) {
        if (edgeCost == 1 && flow.isUsed(edge)) answer++
    }

    print(answer)
}

