private class LongMinHeap(initialCapacity: Int = 16) {
    private var heap = LongArray(initialCapacity)
    private var size = 0

    fun isNotEmpty(): Boolean = size > 0

    fun clear() {
        size = 0
    }

    fun add(value: Long) {
        if (size == heap.size) heap = heap.copyOf(heap.size * 2)
        var i = size++
        while (i > 0) {
            val parent = (i - 1) ushr 1
            if (heap[parent] <= value) break
            heap[i] = heap[parent]
            i = parent
        }
        heap[i] = value
    }

    fun poll(): Long {
        val result = heap[0]
        val last = heap[--size]
        if (size > 0) {
            var i = 0
            while (true) {
                val left = i * 2 + 1
                if (left >= size) break
                var child = left
                val right = left + 1
                if (right < size && heap[right] < heap[left]) child = right
                if (heap[child] >= last) break
                heap[i] = heap[child]
                i = child
            }
            heap[i] = last
        }
        return result
    }
}

private class MinCostMaxFlow(private val vertexCount: Int) {
    private val graph = Array(vertexCount) { ArrayList<Edge>() }

    fun addEdge(from: Int, to: Int, capacity: Int, cost: Int) {
        val forward = Edge(to, graph[to].size, capacity, cost)
        val backward = Edge(from, graph[from].size, 0, -cost)
        graph[from].add(forward)
        graph[to].add(backward)
    }

    fun minCostFlow(source: Int, sink: Int, requiredFlow: Int): Int {
        val inf = Int.MAX_VALUE / 4
        val potential = IntArray(vertexCount)
        val distance = IntArray(vertexCount)
        val previousVertex = IntArray(vertexCount)
        val previousEdge = IntArray(vertexCount)
        val heap = LongMinHeap(1 shl 15)

        var flow = 0
        var totalCost = 0

        while (flow < requiredFlow) {
            java.util.Arrays.fill(distance, inf)
            distance[source] = 0
            heap.clear()
            heap.add(source.toLong())

            while (heap.isNotEmpty()) {
                val state = heap.poll()
                val vertex = (state and 0xffffffffL).toInt()
                val currentDistance = (state ushr 32).toInt()
                if (currentDistance != distance[vertex]) continue

                val edges = graph[vertex]
                for (i in edges.indices) {
                    val edge = edges[i]
                    if (edge.capacity == 0) continue

                    val reducedCost = edge.cost + potential[vertex] - potential[edge.to]
                    val nextDistance = currentDistance + reducedCost

                    if (nextDistance < distance[edge.to]) {
                        distance[edge.to] = nextDistance
                        previousVertex[edge.to] = vertex
                        previousEdge[edge.to] = i
                        heap.add((nextDistance.toLong() shl 32) or (edge.to.toLong() and 0xffffffffL))
                    }
                }
            }

            if (distance[sink] == inf) break

            for (v in 0 until vertexCount) {
                if (distance[v] < inf) potential[v] += distance[v]
            }

            var vertex = sink
            while (vertex != source) {
                val from = previousVertex[vertex]
                val edgeIndex = previousEdge[vertex]
                val edge = graph[from][edgeIndex]

                totalCost += edge.cost
                edge.capacity--
                graph[vertex][edge.reverse].capacity++

                vertex = from
            }

            flow++
        }

        return totalCost
    }
}

