private class MinHeap(initialCapacity: Int = 16) {
    private var nodes = IntArray(initialCapacity)
    private var values = IntArray(initialCapacity)
    private var size = 0

    fun isNotEmpty(): Boolean = size > 0

    fun clear() {
        size = 0
    }

    fun push(node: Int, value: Int) {
        if (size == nodes.size) {
            nodes = nodes.copyOf(nodes.size * 2)
            values = values.copyOf(values.size * 2)
        }

        var index = size++
        while (index > 0) {
            val parent = (index - 1) ushr 1
            if (values[parent] <= value) break
            nodes[index] = nodes[parent]
            values[index] = values[parent]
            index = parent
        }
        nodes[index] = node
        values[index] = value
    }

    fun popNode(): Int {
        val result = nodes[0]
        val lastNode = nodes[--size]
        val lastValue = values[size]

        if (size > 0) {
            var index = 0
            while (true) {
                val left = index * 2 + 1
                if (left >= size) break

                var child = left
                val right = left + 1
                if (right < size && values[right] < values[left]) {
                    child = right
                }
                if (values[child] >= lastValue) break

                nodes[index] = nodes[child]
                values[index] = values[child]
                index = child
            }
            nodes[index] = lastNode
            values[index] = lastValue
        }
        return result
    }

    fun peekValue(): Int = values[0]
}

private class MinCostFlow(
    private val vertexCount: Int,
    maxEdges: Int
) {
    private val head = IntArray(vertexCount) { -1 }
    private val to = IntArray(maxEdges)
    private val next = IntArray(maxEdges)
    private val capacity = IntArray(maxEdges)
    private val cost = IntArray(maxEdges)
    private var edgeCount = 0

    fun addEdge(from: Int, destination: Int, cap: Int, edgeCost: Int) {
        to[edgeCount] = destination
        capacity[edgeCount] = cap
        cost[edgeCount] = edgeCost
        next[edgeCount] = head[from]
        head[from] = edgeCount++

        to[edgeCount] = from
        capacity[edgeCount] = 0
        cost[edgeCount] = -edgeCost
        next[edgeCount] = head[destination]
        head[destination] = edgeCount++
    }

    fun minCost(source: Int, sink: Int, requiredFlow: Int): Int {
        val inf = 1_000_000_000
        val potential = IntArray(vertexCount)
        val distance = IntArray(vertexCount)
        val previousEdge = IntArray(vertexCount)
        val heap = MinHeap(vertexCount * 2)

        var flow = 0
        var totalCost = 0

        while (flow < requiredFlow) {
            java.util.Arrays.fill(distance, inf)
            java.util.Arrays.fill(previousEdge, -1)
            heap.clear()

            distance[source] = 0
            heap.push(source, 0)

            while (heap.isNotEmpty()) {
                val currentDistance = heap.peekValue()
                val vertex = heap.popNode()
                if (currentDistance != distance[vertex]) continue

                var edge = head[vertex]
                while (edge != -1) {
                    if (capacity[edge] > 0) {
                        val destination = to[edge]
                        val reducedCost =
                            cost[edge] + potential[vertex] - potential[destination]
                        val newDistance = currentDistance + reducedCost

                        if (newDistance < distance[destination]) {
                            distance[destination] = newDistance
                            previousEdge[destination] = edge
                            heap.push(destination, newDistance)
                        }
                    }
                    edge = next[edge]
                }
            }

            if (previousEdge[sink] == -1) break

            for (vertex in 0 until vertexCount) {
                if (distance[vertex] < inf) {
                    potential[vertex] += distance[vertex]
                }
            }

            var vertex = sink
            while (vertex != source) {
                val edge = previousEdge[vertex]
                capacity[edge]--
                capacity[edge xor 1]++
                totalCost += cost[edge]
                vertex = to[edge xor 1]
            }

            flow++
        }

        return totalCost
    }
}

