private class LongIntHeap(initialCapacity: Int) {
    private var distances = IntArray(initialCapacity.coerceAtLeast(4))
    private var vertices = IntArray(initialCapacity.coerceAtLeast(4))
    private var size = 0

    fun isNotEmpty(): Boolean = size > 0

    fun push(distance: Int, vertex: Int) {
        if (size == distances.size) {
            distances = distances.copyOf(size * 2)
            vertices = vertices.copyOf(size * 2)
        }

        var index = size++
        while (index > 0) {
            val parent = (index - 1) ushr 1
            if (distances[parent] < distance ||
                (distances[parent] == distance && vertices[parent] <= vertex)
            ) break

            distances[index] = distances[parent]
            vertices[index] = vertices[parent]
            index = parent
        }
        distances[index] = distance
        vertices[index] = vertex
    }

    fun pop(): Long {
        val resultDistance = distances[0]
        val resultVertex = vertices[0]

        --size
        if (size > 0) {
            val lastDistance = distances[size]
            val lastVertex = vertices[size]
            var index = 0

            while (true) {
                val left = index * 2 + 1
                if (left >= size) break
                var child = left
                val right = left + 1

                if (right < size &&
                    (distances[right] < distances[left] ||
                     (distances[right] == distances[left] && vertices[right] < vertices[left]))
                ) {
                    child = right
                }

                if (distances[child] > lastDistance ||
                    (distances[child] == lastDistance && vertices[child] >= lastVertex)
                ) break

                distances[index] = distances[child]
                vertices[index] = vertices[child]
                index = child
            }

            distances[index] = lastDistance
            vertices[index] = lastVertex
        }

        return (resultDistance.toLong() shl 32) or (resultVertex.toLong() and 0xffffffffL)
    }
}

