            if (currentDistance != distance[vertex]) continue

            var edge = head[vertex]
            while (edge != -1) {
                if (capacity[edge] > 0) {
                    val destination = to[edge]
                    val reducedCost = cost[edge] + potential[vertex] - potential[destination]
                    val newDistance = currentDistance + reducedCost

                    if (newDistance < distance[destination]) {
                        distance[destination] = newDistance
                        heap.push(newDistance, destination)
                    }
                }
                edge = next[edge]
            }
        }

        if (distance[sink] == inf) return false

        for (vertex in 0 until vertexCount) {
            if (distance[vertex] < inf) {
                potential[vertex] += distance[vertex]
            }
        }
        return true
    }

    private fun buildLevels(source: Int, sink: Int): Boolean {
        Arrays.fill(level, -1)
        var front = 0
        var back = 0
        queue[back++] = source
        level[source] = 0

        while (front < back) {
            val vertex = queue[front++]
            var edge = head[vertex]

            while (edge != -1) {
                val destination = to[edge]
                if (capacity[edge] > 0 &&
                    level[destination] == -1 &&
                    cost[edge] + potential[vertex] - potential[destination] == 0
                ) {
                    level[destination] = level[vertex] + 1
                    queue[back++] = destination
                }
                edge = next[edge]
            }
        }

        return level[sink] != -1
    }

    private fun findAdmissiblePath(source: Int, sink: Int): Boolean {
        var depth = 0
        stackVertex[0] = source

        while (true) {
            val vertex = stackVertex[depth]

            if (vertex == sink) {
                for (i in 0 until depth) {
                    val edge = stackEdge[i]
                    capacity[edge]--
                    capacity[edge xor 1]++
                }
                return true
            }

            var edge = pointer[vertex]
            while (edge != -1) {
                val destination = to[edge]
                if (capacity[edge] > 0 &&
                    level[destination] == level[vertex] + 1 &&
                    cost[edge] + potential[vertex] - potential[destination] == 0
                ) {
                    break
                }
                edge = next[edge]
            }
            pointer[vertex] = edge

            if (edge == -1) {
                level[vertex] = -1
                if (depth == 0) return false

                depth--
                val parent = stackVertex[depth]
                pointer[parent] = next[stackEdge[depth]]
            } else {
                stackEdge[depth] = edge
                depth++
                stackVertex[depth] = to[edge]
            }
        }
    }

    fun minCostFlow(source: Int, sink: Int, requiredFlow: Int): Int {
        var flow = 0
        var totalCost = 0

        while (flow < requiredFlow && dijkstra(source, sink)) {
            while (flow < requiredFlow && buildLevels(source, sink)) {
                for (vertex in 0 until vertexCount) {
                    pointer[vertex] = head[vertex]
                }

                while (flow < requiredFlow && findAdmissiblePath(source, sink)) {
                    flow++
                    totalCost += potential[sink] - potential[source]
                }
            }
        }

        return totalCost
    }
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val m = scanner.nextInt()
    val cells = n * m
    val grid = IntArray(cells)

    for (i in 0 until cells) {
        grid[i] = scanner.nextInt()
    }

    val source = cells
    val sink = cells + 1
    val vertexCount = cells + 2
    val maxDirectedEdges = cells * 8 + 20
    val flow = MinCostFlow(vertexCount, maxDirectedEdges)

    val dr = intArrayOf(-1, 1, 0, 0)
    val dc = intArrayOf(0, 0, -1, 1)

    for (r in 0 until n) {
        for (c in 0 until m) {
            val vertex = r * m + c
            if ((r + c) and 1 == 0) {
                flow.addEdge(source, vertex, 1, 0)

                for (direction in 0 until 4) {
                    val nr = r + dr[direction]
                    val nc = c + dc[direction]
                    if (nr in 0 until n && nc in 0 until m) {
                        val neighbor = nr * m + nc
                        val edgeCost = if (grid[vertex] == grid[neighbor]) 0 else 1
                        flow.addEdge(vertex, neighbor, 1, edgeCost)
                    }
                }
            } else {
                flow.addEdge(vertex, sink, 1, 0)
            }
        }
    }

    print(flow.minCostFlow(source, sink, cells / 2))
}

