            if (length <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
