    val head = IntArray(n) { -1 }
    val reverseHead = IntArray(n) { -1 }
    val to = IntArray(m)
    val reverseTo = IntArray(m)
    val next = IntArray(m)
    val reverseNext = IntArray(m)

    for (i in 0 until m) {
        val a = fs.nextInt() - 1
        val b = fs.nextInt() - 1

        to[i] = b
        next[i] = head[a]
        head[a] = i

        reverseTo[i] = a
        reverseNext[i] = reverseHead[b]
        reverseHead[b] = i
    }

