    val to = IntArray(m)
    val next = IntArray(m)
    val reverseTo = IntArray(m)
    val reverseNext = IntArray(m)

    for (i in 0 until m) {
        val a = fs.nextInt() - 1
        val b = fs.nextInt() - 1

        to[i] = b
        next[i] = head[a]
        head[a] = i

        reverseTo[i] = a
        reverseNext[i] = reverseHead[b]
        reverseHead[b] = i
    }

    val reachableFromAssignment = BooleanArray(n)
    val canReachUse = BooleanArray(n)
    val queue = IntArray(n)

    var front = 0
    var back = 0

    for (v in 0 until n) {
        if (action[v] == 1) {
            reachableFromAssignment[v] = true
            queue[back++] = v
        }
    }

    while (front < back) {
        val v = queue[front++]
        var edge = head[v]

        while (edge != -1) {
            val u = to[edge]
            if (action[u] != 1 && !reachableFromAssignment[u]) {
                reachableFromAssignment[u] = true
                queue[back++] = u
            }
            edge = next[edge]
        }
    }

    front = 0
    back = 0

    for (v in 0 until n) {
        if (action[v] == 2) {
            canReachUse[v] = true
            queue[back++] = v
        }
    }

    while (front < back) {
        val v = queue[front++]
        var edge = reverseHead[v]

        while (edge != -1) {
            val u = reverseTo[edge]
            if (!canReachUse[u]) {
                canReachUse[u] = true
                if (action[u] != 1) {
                    queue[back++] = u
                }
            }
            edge = reverseNext[edge]
        }
    }

    val output = StringBuilder()
    for (v in 0 until n) {
        output.append(if (reachableFromAssignment[v] && canReachUse[v]) 1 else 0)
        output.append('\n')
    }

    print(output)
}

