private const val LIMIT = 1_000_000
private const val KEY_BASE = 100_000L

private lateinit var primes: IntArray
private val memo = HashMap<Long, Long>()
private val primeMemo = HashMap<Long, Boolean>()

private fun buildPrimes(): IntArray {
    val composite = BooleanArray(LIMIT + 1)
    val list = ArrayList<Int>()

    for (i in 2..LIMIT) {
        if (!composite[i]) {
            list.add(i)
            if (i.toLong() * i <= LIMIT) {
                var j = i * i
                while (j <= LIMIT) {
                    composite[j] = true
                    j += i
                }
            }
        }
    }
    return list.toIntArray()
}

private fun isPrime(n: Long): Boolean {
    if (n < 2) return false
    primeMemo[n]?.let { return it }

    for (pInt in primes) {
        val p = pInt.toLong()
        if (p * p > n) break
        if (n % p == 0L) {
            val result = n == p
            primeMemo[n] = result
            return result
        }
    }

    primeMemo[n] = true
    return true
}

private fun countSolutions(remaining: Long, startIndex: Int): Long {
    if (remaining == 1L) return 1L

    val key = remaining * KEY_BASE + startIndex
    memo[key]?.let { return it }

    val previousPrime = if (startIndex == 0) 1L else primes[startIndex - 1].toLong()
    val finalPrime = remaining - 1

    var result = 0L
    if (finalPrime > previousPrime && isPrime(finalPrime)) {
        result++
    }

    var i = startIndex
    while (i < primes.size) {
        val p = primes[i].toLong()
        if (p * p > remaining) break

        var power = 1L
        var sum = 1L

        while (power <= (remaining - sum) / p) {
            power *= p
            sum += power

            if (remaining % sum == 0L) {
                result += countSolutions(remaining / sum, i + 1)
            }
        }
        i++
    }

    memo[key] = result
    return result
}

