private fun buildPrimes(limit: Int): IntArray {
    val composite = BooleanArray(limit + 1)
    val result = ArrayList<Int>()

    for (i in 2..limit) {
        if (!composite[i]) {
            result.add(i)
            if (i.toLong() * i <= limit) {
