        }
        p += if (p == 2L) 1L else 2L
    }

    if (n > 1) factors.add(n to 1)
    return factors
}

private fun generateDivisors(
    factors: List<Pair<Long, Int>>,
    index: Int,
    current: Long,
    result: MutableList<Long>
) {
    if (index == factors.size) {
        result.add(current)
        return
    }

    val (prime, exponent) = factors[index]
    var multiplier = 1L
    repeat(exponent + 1) {
        generateDivisors(factors, index + 1, current * multiplier, result)
        multiplier *= prime
    }
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val tokenizer = StringTokenizer(reader.readLine())
    val a = tokenizer.nextToken().toLong()

    val divisors = ArrayList<Long>()
    generateDivisors(factorize(a), 0, 1L, divisors)

    val blocks = ArrayList<Block>()

    for (divisor in divisors) {
        val prime = divisor - 1
        if (isPrime(prime)) {
            blocks.add(Block(prime, divisor))
        }
    }

    val primes = sieve(1_000_000)
    for (pInt in primes) {
        val p = pInt.toLong()
        if (p * p > a) break

        var power = p
        var sum = 1L + p

        while (power <= (a - sum) / p) {
            power *= p
            sum += power
            if (a % sum == 0L) {
                blocks.add(Block(p, sum))
            }
        }
    }

    blocks.sortWith(compareBy<Block> { it.prime }.thenBy { it.sum })

    val memo = HashMap<State, Long>()

    fun count(remaining: Long, lastPrime: Long): Long {
        if (remaining == 1L) return 1L

        val state = State(remaining, lastPrime)
        memo[state]?.let { return it }

        var result = 0L

        for (block in blocks) {
            if (block.prime <= lastPrime) continue
            if (block.prime + 1 > remaining) break

            if (remaining % block.sum == 0L) {
                result += count(remaining / block.sum, block.prime)
            }
        }

        memo[state] = result
        return result
    }

    print(count(a, 1L))
}

