    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32) c = readByte()
        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun powers(base: Long, limit: Long): List<Long> {
    val result = ArrayList<Long>()
    var value = 1L
    while (true) {
        result.add(value)
        if (value > limit / base) break
        value *= base
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val x = fs.nextLong()
    val y = fs.nextLong()
    val l = fs.nextLong()
    val r = fs.nextLong()

    val xPowers = powers(x, r)
    val yPowers = powers(y, r)
    val unlucky = TreeSet<Long>()

    for (a in xPowers) {
        for (b in yPowers) {
            if (a > r - b) break
            val sum = a + b
            if (sum >= l) unlucky.add(sum)
        }
    }

    var answer = 0L
    var previous = l - 1

    for (year in unlucky) {
        answer = maxOf(answer, year - previous - 1)
        previous = year
    }
    answer = maxOf(answer, r - previous)

    print(answer)
}

