import java.io.BufferedInputStream

private const val SIZE = 6

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0L
        while (c > 32 && c != -1) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) value else -value
    }
}

private fun normalize(value: Long, mod: Long): Long {
    val result = value % mod
    return if (result < 0) result + mod else result
}

private fun multiplyMatrices(
    a: Array<LongArray>,
    b: Array<LongArray>,
    mod: Long
): Array<LongArray> {
    val result = Array(SIZE) { LongArray(SIZE) }

    for (i in 0 until SIZE) {
        for (k in 0 until SIZE) {
            if (a[i][k] == 0L) continue
            for (j in 0 until SIZE) {
                result[i][j] =
                    (result[i][j] + a[i][k] * b[k][j]) % mod
            }
        }
    }
    return result
}

private fun multiplyMatrixVector(
    matrix: Array<LongArray>,
    vector: LongArray,
    mod: Long
): LongArray {
    val result = LongArray(SIZE)

    for (i in 0 until SIZE) {
        var sum = 0L
        for (j in 0 until SIZE) {
            sum = (sum + matrix[i][j] * vector[j]) % mod
        }
        result[i] = sum
    }
    return result
}

fun main() {
    val fs = FastScanner()

    val n = fs.nextLong()
    val sx = fs.nextLong()
    val sy = fs.nextLong()
    val dx = fs.nextLong()
    val dy = fs.nextLong()
    var t = fs.nextLong()

    var transition = arrayOf(
        longArrayOf(2, 1, 1, 0, 1, 2),
        longArrayOf(1, 2, 0, 1, 1, 2),
        longArrayOf(1, 1, 1, 0, 1, 2),
        longArrayOf(1, 1, 0, 1, 1, 2),
        longArrayOf(0, 0, 0, 0, 1, 1),
        longArrayOf(0, 0, 0, 0, 0, 1)
    )

    for (i in 0 until SIZE) {
        for (j in 0 until SIZE) {
            transition[i][j] %= n
        }
    }

    var state = longArrayOf(
        normalize(sx - 1, n),
        normalize(sy - 1, n),
        normalize(dx, n),
        normalize(dy, n),
        0L,
        1L % n
    )

    while (t > 0) {
        if ((t and 1L) != 0L) {
            state = multiplyMatrixVector(transition, state, n)
        }
        transition = multiplyMatrices(transition, transition, n)
        t = t shr 1
    }

    println("${state[0] + 1} ${state[1] + 1}")
}

