            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32) c = readByte()

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }
}

private fun multiply(
    a: Array<LongArray>,
    b: Array<LongArray>,
    mod: Long
): Array<LongArray> {
    val size = a.size
    val result = Array(size) { LongArray(size) }

    for (i in 0 until size) {
        for (k in 0 until size) {
            if (a[i][k] == 0L) continue
            for (j in 0 until size) {
                result[i][j] =
                    (result[i][j] + a[i][k] * b[k][j] % mod) % mod
            }
        }
    }
    return result
}

private fun multiply(
    matrix: Array<LongArray>,
    vector: LongArray,
    mod: Long
): LongArray {
    val result = LongArray(matrix.size)
    for (i in matrix.indices) {
        var sum = 0L
        for (j in vector.indices) {
            sum = (sum + matrix[i][j] * vector[j] % mod) % mod
        }
        result[i] = sum
    }
    return result
}

private fun normalize(value: Long, mod: Long): Long {
    val result = value % mod
    return if (result < 0) result + mod else result
}

