private const val MOD = 998244353L

private fun multiply(a: LongArray, b: LongArray, size: Int): LongArray {
    val result = LongArray(size * size)
    for (i in 0 until size) {
        val row = i * size
        for (k in 0 until size) {
            val av = a[row + k]
            if (av == 0L) continue
            val kRow = k * size
            for (j in 0 until size) {
                val bv = b[kRow + j]
                if (bv == 0L) continue
                val index = row + j
                result[index] = (result[index] + av * bv) % MOD
            }
        }
    }
    return result
}

private fun power(baseInput: LongArray, exponentInput: Int, size: Int): LongArray {
    var base = baseInput
    var exponent = exponentInput
    var result = LongArray(size * size)
    for (i in 0 until size) result[i * size + i] = 1L

    while (exponent > 0) {
        if ((exponent and 1) != 0) {
            result = multiply(result, base, size)
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            base = multiply(base, base, size)
        }
    }
    return result
}

private fun add(matrix: LongArray, size: Int, from: Int, to: Int) {
    val index = from * size + to
    matrix[index]++
    if (matrix[index] == MOD) matrix[index] = 0L
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = StringTokenizer(reader.readLine()).nextToken().toInt()

    val size = 16
    val transition = LongArray(size * size)

    for (mask in 0 until 4) {
        for (flags in 0 until 4) {
            val from = mask * 4 + flags
            val shifted = mask shr 1

            fun addNonFlowerTransition(nextMask: Int) {
                for (nextFlags in 0 until 4) {
                    if ((nextFlags and flags) == flags) {
                        add(
                            transition,
                            size,
                            from,
                            nextMask * 4 + nextFlags
                        )
                    }
                }
            }

            if ((mask and 1) != 0) {
                addNonFlowerTransition(shifted)
            } else {
                if (flags == 3) {
                    add(transition, size, from, shifted * 4)
                }

                if ((mask and 2) == 0) {
                    addNonFlowerTransition(shifted or 1)
                }

                addNonFlowerTransition(shifted or 2)
            }
        }
    }

    val dimerSize = 4
    val dimerTransition = LongArray(dimerSize * dimerSize)

    for (mask in 0 until 4) {
        val shifted = mask shr 1
        if ((mask and 1) != 0) {
            add(dimerTransition, dimerSize, mask, shifted)
        } else {
            if ((mask and 2) == 0) {
                add(dimerTransition, dimerSize, mask, shifted or 1)
            }
            add(dimerTransition, dimerSize, mask, shifted or 2)
        }
    }

    val powered = power(transition, n, size)
    var total = 0L
    for (i in 0 until size) {
        total += powered[i * size + i]
        if (total >= MOD) total -= MOD
    }

    val dimerPowered = power(dimerTransition, n, dimerSize)
    var noOpposite = 0L
    for (i in 0 until dimerSize) {
        noOpposite += dimerPowered[i * dimerSize + i]
        if (noOpposite >= MOD) noOpposite -= MOD
    }

    val answer = (total - 4L * noOpposite % MOD + MOD) % MOD
    print(answer)
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun isLucky(value: Int): Boolean {
    if (value <= 0) return false
    var x = value
    while (x > 0) {
        val digit = x % 10
        if (digit != 4 && digit != 7) return false
        x /= 10
    }
    return true
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextLong().toInt()
    val k = scanner.nextLong()

    val factorial = LongArray(14)
    factorial[0] = 1L
    for (i in 1..13) factorial[i] = factorial[i - 1] * i

    val suffixLength = minOf(n, 13)
    if (k > factorial[suffixLength]) {
        print("-1")
        return
    }

    val suffixStart = n - suffixLength + 1
    val available = MutableList(suffixLength) { suffixStart + it }
    val permutation = IntArray(suffixLength)
    var rank = k - 1

    for (i in 0 until suffixLength) {
        val remaining = suffixLength - i
        val blockSize = factorial[remaining - 1]
        val index = (rank / blockSize).toInt()
        rank %= blockSize
        permutation[i] = available.removeAt(index)
    }

    var answer = 0

    fun visitLucky(number: Long) {
        if (number > n) return

        if (number > 0) {
            val position = number.toInt()
            val value = if (position < suffixStart) {
                position
            } else {
                permutation[position - suffixStart]
            }

            if (isLucky(value)) answer++
        }

        visitLucky(number * 10 + 4)
        visitLucky(number * 10 + 7)
    }

    visitLucky(0)
    print(answer)
}

