    for (i in 1..13) factorial[i] = factorial[i - 1] * i

    val suffixSize = minOf(n, 13)
    if (k > factorial[suffixSize]) {
        print("-1")
        return
    }

    val offset = n - suffixSize
    val available = MutableList(suffixSize) { offset + it + 1 }
    val permutation = IntArray(suffixSize)
    var rank = k - 1

    for (i in 0 until suffixSize) {
        val blockSize = factorial[suffixSize - i - 1]
        val index = (rank / blockSize).toInt()
        rank %= blockSize
        permutation[i] = available.removeAt(index)
    }

    fun isLucky(value: Int): Boolean {
        var x = value
        while (x > 0) {
            val digit = x % 10
            if (digit != 4 && digit != 7) return false
            x /= 10
        }
        return true
    }

    var answer = 0

    fun generateLucky(value: Long) {
        if (value > n) return

        if (value > 0) {
            val position = value.toInt()
            val mappedValue = if (position <= offset) {
                position
            } else {
                permutation[position - offset - 1]
            }

            if (isLucky(mappedValue)) answer++
        }

        generateLucky(value * 10 + 4)
        generateLucky(value * 10 + 7)
    }

    generateLucky(0)
