import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val l = st.nextToken().toLong()
    val r = st.nextToken().toLong()

    var answer = 0L
    var lower = 1L
    var powerOfTen = 10L

    while (lower <= r) {
        val upper = powerOfTen - 1
        val left = maxOf(l, lower)
        val right = minOf(r, upper)

        if (left <= right) {
            val middle = upper / 2
            val candidates = longArrayOf(left, right, middle, middle + 1)

            for (n in candidates) {
                if (n in left..right) {
                    answer = maxOf(answer, n * (upper - n))
                }
            }
        }

        lower = powerOfTen
        powerOfTen *= 10
    }

    print(answer)
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32) c = readByte()
        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()
    val l = fs.nextLong()
    val r = fs.nextLong()

    var answer = 0L
    var lowerDigitBound = 1L
    var powerOfTen = 10L

    repeat(10) {
        val segmentLeft = maxOf(l, lowerDigitBound)
        val segmentRight = minOf(r, powerOfTen - 1)

        if (segmentLeft <= segmentRight) {
            val complementBase = powerOfTen - 1
            val midpoint = complementBase / 2
            val candidate = midpoint.coerceIn(segmentLeft, segmentRight)
            val weight = candidate * (complementBase - candidate)
            answer = maxOf(answer, weight)
        }

        lowerDigitBound = powerOfTen
        powerOfTen *= 10
    }

    print(answer)
}

