import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 1_000_000_007L

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())

    val n = st.nextToken().toInt()
    val x = st.nextToken().toInt()
    val pos = st.nextToken().toInt()

    var smaller = 0
    var greater = 0
    var left = 0
    var right = n

    while (left < right) {
        val mid = (left + right) / 2
        if (mid <= pos) {
            if (mid < pos) smaller++
            left = mid + 1
        } else {
            greater++
            right = mid
        }
    }

    if (smaller > x - 1 || greater > n - x) {
        print(0)
        return
    }

    var answer = 1L

    for (i in 0 until smaller) {
        answer = answer * (x - 1 - i) % MOD
    }

    for (i in 0 until greater) {
        answer = answer * (n - x - i) % MOD
    }

    val remaining = n - smaller - greater - 1
    for (i in 2..remaining) {
        answer = answer * i % MOD
    }

    print(answer)
}

