fun countUpTo(x: Long): Long {
    if (x <= 0) return 0
    var count = 0L

    for (length in 2..60) {
        val allOnes = (1L shl length) - 1
        for (zeroPosition in 0 until length - 1) {
            val value = allOnes xor (1L shl zeroPosition)
            if (value <= x) count++
        }
    }

    return count
}

