private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= length) {
            length = input.read(buffer)
            ptr = 0
            if (length <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c >= 0)
        while (c > 32) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private data class Option(val ch: Int, val to: Int)
private data class Edge(val to: Int, val weight: Int)

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = result * base % MOD
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    val size = sequence.size
    var c = LongArray(size + 1)
    var bPoly = LongArray(size + 1)
    c[0] = 1L
    bPoly[0] = 1L

    var cMax = 0
    var bMax = 0
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (position in sequence.indices) {
        var discrepancy = 0L
        for (i in 0..length) {
            discrepancy = (discrepancy + c[i] * sequence[position - i]) % MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.copyOf()
        val oldCMax = cMax
        val factor = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD

        for (i in 0..bMax) {
            val index = i + shift
            var value = c[index] - factor * bPoly[i] % MOD
            if (value < 0) value += MOD
            c[index] = value
            if (value != 0L && index > cMax) cMax = index
        }

        if (2 * length <= position) {
            length = position + 1 - length
            bPoly = oldC
            bMax = oldCMax
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    val recurrence = LongArray(length)
    for (i in 0 until length) {
        recurrence[i] = if (c[i + 1] == 0L) 0L else MOD - c[i + 1]
    }
    return recurrence
}

private fun combinePolynomials(
    a: LongArray,
    b: LongArray,
    recurrence: LongArray
): LongArray {
    val length = recurrence.size
    val product = LongArray(2 * length - 1)

    for (i in 0 until length) {
        if (a[i] == 0L) continue
        for (j in 0 until length) {
            if (b[j] == 0L) continue
            product[i + j] = (product[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in 2 * length - 2 downTo length) {
        val value = product[degree]
        if (value == 0L) continue
        for (j in 1..length) {
            val index = degree - j
            product[index] = (product[index] + value * recurrence[j - 1]) % MOD
        }
    }

    return product.copyOf(length)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]

    val length = recurrence.size
    if (length == 0) return 0L

    var result = LongArray(length)
    result[0] = 1L

    var base = LongArray(length)
    if (length == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combinePolynomials(result, base, recurrence)
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            base = combinePolynomials(base, base, recurrence)
        }
    }

    var answer = 0L
    for (i in 0 until length) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextLong()
    val words = Array(n) { fs.next() }

    val statusId = HashMap<String, Int>()
    val statuses = ArrayList<String>()

    fun addStatus(s: String) {
        if (!statusId.containsKey(s)) {
            statusId[s] = statuses.size
            statuses.add(s)
        }
    }

    addStatus("")
    for (word in words) {
        for (position in 1 until word.length) {
            addStatus(word.substring(position))
        }
    }

    val statusCount = statuses.size
    val options = Array(statusCount) { ArrayList<Option>() }

    for (id in 0 until statusCount) {
        val suffix = statuses[id]
        if (suffix.isNotEmpty()) {
            options[id].add(
                Option(
                    suffix[0] - 'a',
                    statusId[suffix.substring(1)]!!
                )
            )
        } else {
            for (word in words) {
                options[id].add(
                    Option(
                        word[0] - 'a',
                        statusId[word.substring(1)]!!
                    )
                )
            }
        }
    }

    val totalPairs = statusCount * statusCount
    val allEdges = arrayOfNulls<MutableList<Edge>>(totalPairs)
    val reachable = BooleanArray(totalPairs)
    val queue = IntArray(totalPairs)
    var head = 0
    var tail = 0

    val startOld = 0
    reachable[startOld] = true
    queue[tail++] = startOld

    while (head < tail) {
        val state = queue[head++]
        val left = state / statusCount
        val right = state % statusCount

        val destinations = IntArray(64)
        val weights = IntArray(64)
        var edgeCount = 0

        for (leftOption in options[left]) {
            for (rightOption in options[right]) {
                if (leftOption.ch != rightOption.ch) continue
                val destination = leftOption.to * statusCount + rightOption.to

                var found = -1
                for (i in 0 until edgeCount) {
                    if (destinations[i] == destination) {
                        found = i
                        break
                    }
                }

                if (found >= 0) {
                    weights[found]++
                } else {
                    destinations[edgeCount] = destination
                    weights[edgeCount] = 1
                    edgeCount++
                }
            }
        }

        val list = ArrayList<Edge>(edgeCount)
        for (i in 0 until edgeCount) {
            val destination = destinations[i]
            list.add(Edge(destination, weights[i]))
            if (!reachable[destination]) {
                reachable[destination] = true
                queue[tail++] = destination
            }
        }
        allEdges[state] = list
    }

    val reverse = arrayOfNulls<MutableList<Int>>(totalPairs)
    for (state in 0 until totalPairs) {
        if (!reachable[state]) continue
        for (edge in allEdges[state] ?: emptyList()) {
            var list = reverse[edge.to]
            if (list == null) {
                list = ArrayList()
                reverse[edge.to] = list
            }
            list.add(state)
        }
    }

    val canReturn = BooleanArray(totalPairs)
    head = 0
    tail = 0
    canReturn[startOld] = true
    queue[tail++] = startOld

    while (head < tail) {
        val state = queue[head++]
        for (previous in reverse[state] ?: emptyList()) {
            if (!canReturn[previous]) {
                canReturn[previous] = true
                queue[tail++] = previous
            }
        }
    }

    val newId = IntArray(totalPairs) { -1 }
    var stateCount = 0
    for (state in 0 until totalPairs) {
        if (reachable[state] && canReturn[state]) {
            newId[state] = stateCount++
        }
    }

    val graph = Array(stateCount) { ArrayList<Edge>() }
    for (oldState in 0 until totalPairs) {
        val from = newId[oldState]
        if (from < 0) continue
        for (edge in allEdges[oldState] ?: emptyList()) {
            val to = newId[edge.to]
            if (to >= 0) graph[from].add(Edge(to, edge.weight))
        }
    }

    val start = newId[startOld]
    val termCount = 2 * stateCount + 5
    val sequence = LongArray(termCount)
    var current = LongArray(stateCount)
    current[start] = 1L

    for (step in 0 until termCount) {
        sequence[step] = current[start]

        val next = LongArray(stateCount)
        for (state in 0 until stateCount) {
            val value = current[state]
            if (value == 0L) continue
            for (edge in graph[state]) {
                next[edge.to] =
                    (next[edge.to] + value * edge.weight.toLong()) % MOD
            }
        }
        current = next
    }

    if (m < sequence.size) {
        println(sequence[m.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    println(linearRecurrenceNth(initial, recurrence, m))
}

