private fun compatiblePrefix(a: String, b: String): Int {
    val length = minOf(a.length, b.length)
    for (i in 0 until length) {
        if (a[i] != b[i]) return -1
    }
    return length
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    var c = mutableListOf(1L)
    var b = mutableListOf(1L)
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (index in sequence.indices) {
        var discrepancy = sequence[index]
        for (i in 1..length) {
            discrepancy = (discrepancy + c[i] * sequence[index - i]) % MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.toMutableList()
        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD
        val requiredSize = b.size + shift
        while (c.size < requiredSize) c.add(0L)

        for (i in b.indices) {
            val position = i + shift
            c[position] = (c[position] - coefficient * b[i] % MOD + MOD) % MOD
        }

        if (2 * length <= index) {
            length = index + 1 - length
            b = oldC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    val recurrence = LongArray(length)
    for (i in 0 until length) {
        recurrence[i] = (MOD - c[i + 1]) % MOD
    }
    return recurrence
}

private fun combinePolynomials(
    a: LongArray,
    b: LongArray,
    recurrence: LongArray
): LongArray {
    val size = recurrence.size
    val product = LongArray(2 * size - 1)

    for (i in 0 until size) {
        if (a[i] == 0L) continue
        for (j in 0 until size) {
            if (b[j] == 0L) continue
            product[i + j] = (product[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in product.lastIndex downTo size) {
        val value = product[degree]
        if (value == 0L) continue
        for (j in 0 until size) {
            val target = degree - size + j
            product[target] = (product[target] + value * recurrence[j]) % MOD
        }
    }

    return product.copyOf(size)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]

    val size = recurrence.size
    if (size == 0) return 0L

    var result = LongArray(size)
    result[0] = 1L

    var power = LongArray(size)
    if (size == 1) {
        power[0] = recurrence[0]
    } else {
        power[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combinePolynomials(result, power, recurrence)
        }
        power = combinePolynomials(power, power, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until size) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextLong()
    val words = Array(n) { fs.next() }

    val suffixSet = LinkedHashSet<String>()
    for (word in words) {
        for (start in 1 until word.length) {
            suffixSet.add(word.substring(start))
        }
    }

    val suffixes = suffixSet.toList()
    val suffixIndex = HashMap<String, Int>()
    for (i in suffixes.indices) {
        suffixIndex[suffixes[i]] = i
    }

    val suffixCount = suffixes.size
    val stateCount = 1 + 2 * suffixCount

    fun leftState(suffix: String): Int = 1 + suffixIndex.getValue(suffix)
    fun rightState(suffix: String): Int = 1 + suffixCount + suffixIndex.getValue(suffix)

    val edges = ArrayList<Edge>()

    for (leftWord in words) {
        for (rightWord in words) {
            val matched = compatiblePrefix(leftWord, rightWord)
            if (matched < 0) continue

            val to = when {
                leftWord.length > rightWord.length ->
                    leftState(leftWord.substring(matched))
                rightWord.length > leftWord.length ->
                    rightState(rightWord.substring(matched))
                else -> 0
            }
            edges.add(Edge(0, to, matched))
        }
    }

    for (suffix in suffixes) {
        val leftFrom = leftState(suffix)
        val rightFrom = rightState(suffix)

        for (word in words) {
            val matched = compatiblePrefix(suffix, word)
            if (matched < 0) continue

            val leftTo = when {
                suffix.length > word.length -> leftState(suffix.substring(matched))
                word.length > suffix.length -> rightState(word.substring(matched))
                else -> 0
            }
            edges.add(Edge(leftFrom, leftTo, matched))

            val rightTo = when {
                suffix.length > word.length -> rightState(suffix.substring(matched))
                word.length > suffix.length -> leftState(word.substring(matched))
                else -> 0
            }
            edges.add(Edge(rightFrom, rightTo, matched))
        }
    }

    val degreeBound = 5 * stateCount
    val termCount = 2 * degreeBound + 10
    val dp = Array(termCount) { LongArray(stateCount) }
    val sequence = LongArray(termCount)
    dp[0][0] = 1L

    for (time in 0 until termCount) {
        sequence[time] = dp[time][0]
        for (edge in edges) {
            val nextTime = time + edge.weight
            if (nextTime >= termCount) continue
            val value = dp[time][edge.from]
            if (value == 0L) continue

            var updated = dp[nextTime][edge.to] + value
            if (updated >= MOD) updated -= MOD
            dp[nextTime][edge.to] = updated
        }
    }

    if (m < termCount.toLong()) {
        print(sequence[m.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    print(linearRecurrenceNth(initial, recurrence, m))
}

import java.io.BufferedInputStream

private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val result = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c >= 0)
        while (c > 32 && c >= 0) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private data class State(val side: Int, val residual: String)
private data class Edge(val to: Int, val weight: Int)

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = result * base % MOD
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    var c = mutableListOf(1L)
    var b = mutableListOf(1L)
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (n in sequence.indices) {
        var discrepancy = sequence[n]
        for (i in 1..length) {
            discrepancy = (discrepancy + c[i] * sequence[n - i]) % MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.toMutableList()
        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD

        while (c.size < b.size + shift) c.add(0L)
        for (i in b.indices) {
            val index = i + shift
            c[index] = (c[index] - coefficient * b[i]) % MOD
            if (c[index] < 0) c[index] += MOD
        }

        if (2 * length <= n) {
            length = n + 1 - length
            b = oldC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    return LongArray(length) { i ->
        if (c[i + 1] == 0L) 0L else MOD - c[i + 1]
    }
}

private fun combine(a: LongArray, b: LongArray, recurrence: LongArray): LongArray {
    val length = recurrence.size
    val temporary = LongArray(2 * length - 1)

    for (i in 0 until length) {
        if (a[i] == 0L) continue
        for (j in 0 until length) {
            if (b[j] == 0L) continue
            temporary[i + j] = (temporary[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in temporary.lastIndex downTo length) {
        val value = temporary[degree]
        if (value == 0L) continue
        for (j in 1..length) {
            temporary[degree - j] =
                (temporary[degree - j] + value * recurrence[j - 1]) % MOD
        }
    }

    return temporary.copyOf(length)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]
    val length = recurrence.size
    if (length == 0) return 0L

    var result = LongArray(length)
    result[0] = 1L

    var base = LongArray(length)
    if (length == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combine(result, base, recurrence)
        }
        base = combine(base, base, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until length) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val targetLength = scanner.nextLong()
    val words = Array(n) { scanner.next() }

    val suffixes = linkedSetOf<String>()
    for (word in words) {
        for (i in 1 until word.length) {
            suffixes.add(word.substring(i))
        }
    }

    val states = ArrayList<State>()
    val stateId = HashMap<State, Int>()

    fun addState(state: State) {
        if (state !in stateId) {
            stateId[state] = states.size
            states.add(state)
        }
    }

    addState(State(0, ""))
    for (suffix in suffixes) addState(State(1, suffix))
    for (suffix in suffixes) addState(State(2, suffix))

    val graph = Array(states.size) { ArrayList<Edge>() }

    fun getState(side: Int, residual: String): Int {
        return stateId[State(side, residual)]!!
    }

    for (top in words) {
        for (bottom in words) {
            when {
                top == bottom -> {
                    graph[0].add(Edge(0, top.length))
                }
                top.startsWith(bottom) -> {
                    val residual = top.substring(bottom.length)
                    graph[0].add(Edge(getState(1, residual), bottom.length))
                }
                bottom.startsWith(top) -> {
                    val residual = bottom.substring(top.length)
                    graph[0].add(Edge(getState(2, residual), top.length))
                }
            }
        }
    }

    for (id in 1 until states.size) {
        val state = states[id]
        val residual = state.residual
        for (word in words) {
            when {
                residual == word -> {
                    graph[id].add(Edge(0, residual.length))
                }
                residual.startsWith(word) -> {
                    val nextResidual = residual.substring(word.length)
                    graph[id].add(Edge(getState(state.side, nextResidual), word.length))
                }
                word.startsWith(residual) -> {
                    val nextResidual = word.substring(residual.length)
                    val oppositeSide = if (state.side == 1) 2 else 1
                    graph[id].add(Edge(getState(oppositeSide, nextResidual), residual.length))
                }
            }
        }
    }

    val maximumRecurrenceLength = states.size * 5
    val sampleCount = maximumRecurrenceLength * 2 + 10
    val dp = Array(sampleCount) { LongArray(states.size) }
    dp[0][0] = 1L

    for (length in 0 until sampleCount) {
        for (state in states.indices) {
            val value = dp[length][state]
            if (value == 0L) continue

            for (edge in graph[state]) {
                val nextLength = length + edge.weight
                if (nextLength >= sampleCount) continue
                var updated = dp[nextLength][edge.to] + value
                if (updated >= MOD) updated -= MOD
                dp[nextLength][edge.to] = updated
            }
        }
    }

    val sequence = LongArray(sampleCount) { dp[it][0] }
    if (targetLength < sampleCount) {
        print(sequence[targetLength.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    print(linearRecurrenceNth(sequence, recurrence, targetLength))
}

import java.io.BufferedInputStream

private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c >= 0)

        while (c > 32) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private data class Edge(val to: Int, val length: Int)

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % MOD
        }
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    var c = mutableListOf(1L)
    var b = mutableListOf(1L)
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (index in sequence.indices) {
        var discrepancy = sequence[index]
        for (i in 1..length) {
            discrepancy += c[i] * sequence[index - i] % MOD
            if (discrepancy >= MOD) discrepancy -= MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD
        val previousC = c.toMutableList()

        val requiredSize = b.size + shift
        while (c.size < requiredSize) c.add(0L)

        for (i in b.indices) {
            val subtract = coefficient * b[i] % MOD
            var value = c[i + shift] - subtract
            if (value < 0) value += MOD
            c[i + shift] = value
        }

        if (2 * length <= index) {
            length = index + 1 - length
            b = previousC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    val recurrence = LongArray(length)
    for (i in 1..length) {
        recurrence[i - 1] = if (c[i] == 0L) 0L else MOD - c[i]
    }
    return recurrence
}

private fun combine(a: LongArray, b: LongArray, recurrence: LongArray): LongArray {
    val n = recurrence.size
    val product = LongArray(2 * n - 1)

    for (i in 0 until n) {
        if (a[i] == 0L) continue
        for (j in 0 until n) {
            if (b[j] == 0L) continue
            val add = a[i] * b[j] % MOD
            var value = product[i + j] + add
            if (value >= MOD) value -= MOD
            product[i + j] = value
        }
    }

    for (degree in 2 * n - 2 downTo n) {
        val value = product[degree]
        if (value == 0L) continue

        for (j in 1..n) {
            val add = value * recurrence[j - 1] % MOD
            val target = degree - j
            var updated = product[target] + add
            if (updated >= MOD) updated -= MOD
            product[target] = updated
        }
    }

    return product.copyOf(n)
}

private fun nthTerm(initial: LongArray, recurrence: LongArray, index: Long): Long {
    if (index < initial.size) return initial[index.toInt()]

    val n = recurrence.size
    if (n == 0) return 0L

    var result = LongArray(n)
    result[0] = 1L

    var base = LongArray(n)
    if (n == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combine(result, base, recurrence)
        }
        base = combine(base, base, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until n) {
        answer += result[i] * initial[i] % MOD
        if (answer >= MOD) answer -= MOD
    }
    return answer
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val targetLength = fs.nextLong()
    val words = Array(n) { fs.next() }
    val maxWordLength = words.maxOf { it.length }

    val suffixes = linkedSetOf<String>()
    for (word in words) {
        for (cut in 1 until word.length) {
            suffixes.add(word.substring(cut))
        }
    }

    val sides = mutableListOf(0)
    val residuals = mutableListOf("")
    val stateIndex = HashMap<String, Int>()

    fun stateKey(side: Int, residual: String) = "$side#$residual"

    for (suffix in suffixes) {
        val index = sides.size
        sides.add(1)
        residuals.add(suffix)
        stateIndex[stateKey(1, suffix)] = index
    }
    for (suffix in suffixes) {
        val index = sides.size
        sides.add(2)
        residuals.add(suffix)
        stateIndex[stateKey(2, suffix)] = index
    }

    val stateCount = sides.size
    val edges = Array(stateCount) { mutableListOf<Edge>() }

    fun addComparison(
        from: Int,
        first: String,
        firstSide: Int,
        second: String,
        secondSide: Int
    ) {
        val commonLength = minOf(first.length, second.length)
        for (i in 0 until commonLength) {
            if (first[i] != second[i]) return
        }

        val target = when {
            first.length == second.length -> 0
            first.length > second.length -> {
                val residual = first.substring(commonLength)
                stateIndex[stateKey(firstSide, residual)]!!
            }
            else -> {
                val residual = second.substring(commonLength)
                stateIndex[stateKey(secondSide, residual)]!!
            }
        }

        edges[from].add(Edge(target, commonLength))
    }

    for (firstWord in words) {
        for (secondWord in words) {
            addComparison(0, firstWord, 1, secondWord, 2)
        }
    }

    for (state in 1 until stateCount) {
        val residual = residuals[state]
        if (sides[state] == 1) {
            for (word in words) {
                addComparison(state, residual, 1, word, 2)
            }
        } else {
            for (word in words) {
                addComparison(state, residual, 2, word, 1)
            }
        }
    }

    val recurrenceBound = stateCount * maxWordLength
    val termCount = 2 * recurrenceBound + 5
    val dp = Array(termCount) { LongArray(stateCount) }
    dp[0][0] = 1L

    for (length in 0 until termCount) {
        for (state in 0 until stateCount) {
            val ways = dp[length][state]
            if (ways == 0L) continue

            for (edge in edges[state]) {
                val nextLength = length + edge.length
                if (nextLength >= termCount) continue

                var value = dp[nextLength][edge.to] + ways
                if (value >= MOD) value -= MOD
                dp[nextLength][edge.to] = value
            }
        }
    }

    val sequence = LongArray(termCount) { dp[it][0] }

    if (targetLength < termCount) {
        print(sequence[targetLength.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    print(nthTerm(initial, recurrence, targetLength))
}

